package com.wedo.backend.journey;
import static com.wedo.backend.journey.ActionDtos.*;
import com.wedo.backend.common.error.*;
import com.wedo.backend.task.service.TaskService;
import com.wedo.backend.task.entity.TaskStatus;
import com.wedo.backend.task.dto.UpdateTaskStatusRequest;
import com.wedo.backend.moment.MomentDtos;
import com.wedo.backend.media.dto.*;
import com.wedo.backend.media.service.MediaReferenceService;
import com.wedo.backend.media.storage.ObjectStorageService;
import java.sql.Timestamp;
import java.time.Duration;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true)
public class TaskEvidenceService {
 final JdbcTemplate db;final TaskService tasks;final JourneyService journey;final TaskEvidencePolicy policy;final MediaReferenceService refs;final ObjectStorageService storage;final com.wedo.backend.realtime.RealtimePublisher events;
 @jakarta.persistence.PersistenceContext jakarta.persistence.EntityManager em;
 public TaskEvidenceService(JdbcTemplate db,TaskService tasks,JourneyService journey,TaskEvidencePolicy policy,MediaReferenceService refs,ObjectStorageService storage,com.wedo.backend.realtime.RealtimePublisher events){this.events=events;this.db=db;this.tasks=tasks;this.journey=journey;this.policy=policy;this.refs=refs;this.storage=storage;}
 Map<String,Object> lock(UUID task,UUID actor){var t=tasks.get(task,actor);journey.mutable(t.activityId(),actor);var row=db.queryForMap("SELECT * FROM tasks WHERE id=? FOR UPDATE",task);em.refresh(em.find(com.wedo.backend.task.entity.TaskEntity.class,task));return row;}
 boolean manager(UUID task,UUID actor){return tasks.get(task,actor).permissions().canEdit();}
 boolean assigned(UUID task,UUID actor){return Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM task_assignees WHERE task_id=? AND user_id=?)",Boolean.class,task,actor));}
 void emit(UUID task,UUID actor){var t=tasks.get(task,actor);var a=journey.readable(t.activityId(),actor);events.activityResource("TASK_EVIDENCE_CHANGED","TASK",task,t.activityId(),a.activity().getGroupId(),null);}
 MomentDtos.Author author(UUID id){return db.queryForObject("SELECT id,COALESCE(display_name,username::text) name,avatar_storage_key FROM users WHERE id=?",(rs,n)->new MomentDtos.Author(id,rs.getString("name"),rs.getString("avatar_storage_key")),id);}
 Evidence view(Map<String,Object> e,UUID actor){UUID task=(UUID)e.get("task_id"),id=(UUID)e.get("id"),user=(UUID)e.get("author_id");boolean current=Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM tasks t JOIN task_assignees a ON a.task_id=t.id AND a.user_id=? JOIN activities act ON act.id=t.activity_id JOIN group_memberships member ON member.group_id=act.group_id AND member.user_id=a.user_id AND member.status='ACTIVE' JOIN users author ON author.id=a.user_id AND author.status='ACTIVE' WHERE t.id=? AND t.updated_at=? AND NOT EXISTS(SELECT 1 FROM group_bans b WHERE b.group_id=act.group_id AND b.user_id=a.user_id AND b.unbanned_at IS NULL))",Boolean.class,user,task,e.get("task_snapshot")));var reviews=db.queryForList("SELECT r.reason,u.display_name FROM task_evidence_reviews r JOIN users u ON u.id=r.reviewer_id WHERE r.evidence_id=?",id);return new Evidence(id,author(user),Source.valueOf((String)e.get("source")),(String)e.get("caption"),(String)e.get("status"),((Timestamp)e.get("created_at")).toInstant(),current,"PENDING".equals(e.get("status"))&&manager(task,actor)&&!actor.equals(user),db.query("SELECT * FROM task_evidence_media WHERE evidence_id=? ORDER BY sort_order,id",(rs,n)->new MomentDtos.Media(rs.getObject("id",UUID.class),rs.getString("content_type"),rs.getString("file_name"),rs.getLong("file_size"),rs.getInt("sort_order")),id),reviews.isEmpty()?null:(String)reviews.getFirst().get("display_name"),reviews.isEmpty()?null:(String)reviews.getFirst().get("reason"));}
 public java.util.List<com.wedo.backend.task.dto.TaskResponse> stopTasks(UUID activity,UUID stop,UUID actor){journey.readable(activity,actor);journey.row(activity,stop);return db.queryForList("SELECT t.id FROM tasks t JOIN task_execution e ON e.task_id=t.id WHERE e.stop_id=? AND t.activity_id=? ORDER BY t.created_at,t.id",UUID.class,stop,activity).stream().map(id->tasks.get(id,actor)).toList();}
 public Execution get(UUID task,UUID actor,UUID before){var t=tasks.get(task,actor);journey.readable(t.activityId(),actor);var cfg=db.queryForList("SELECT stop_id FROM task_execution WHERE task_id=?",task);var rows=db.queryForList("SELECT * FROM task_evidence WHERE task_id=? AND (?::uuid IS NULL OR (created_at,id)<(SELECT created_at,id FROM task_evidence WHERE id=? AND task_id=?)) ORDER BY created_at DESC,id DESC LIMIT 21",task,before,before,task);boolean mutable=t.permissions().canChangeStatus()&&t.status()!=TaskStatus.DONE;return new Execution(t,Mode.valueOf(policy.mode(task)),cfg.isEmpty()?null:(UUID)cfg.getFirst().get("stop_id"),t.permissions().canEdit()&&t.status()!=TaskStatus.DONE,mutable&&!policy.mode(task).equals("NONE"),rows.stream().limit(20).map(e->view(e,actor)).toList(),rows.size()>20?(UUID)rows.get(19).get("id"):null);}
 @Transactional public Execution configure(UUID task,UUID actor,Configure r){var t=lock(task,actor);if(!manager(task,actor))throw journey.denied();var previous=db.queryForList("SELECT stop_id,evidence_mode FROM task_execution WHERE task_id=?",task);if(policy.mode(task).equals(r.mode().name())&&Objects.equals(previous.isEmpty()?null:previous.getFirst().get("stop_id"),r.stopId()))return get(task,actor,null);if("DONE".equals(t.get("status")))throw journey.denied();if(r.stopId()!=null)journey.row((UUID)t.get("activity_id"),r.stopId());db.update("INSERT INTO task_execution(task_id,stop_id,evidence_mode) VALUES (?,?,?) ON CONFLICT(task_id) DO UPDATE SET stop_id=excluded.stop_id,evidence_mode=excluded.evidence_mode",task,r.stopId(),r.mode().name());db.update("UPDATE task_evidence SET status='SUPERSEDED',updated_at=clock_timestamp() WHERE task_id=? AND status='PENDING'",task);if(!previous.isEmpty()&&previous.getFirst().get("stop_id")!=null&&!Objects.equals(previous.getFirst().get("stop_id"),r.stopId())){var a=journey.readable((UUID)t.get("activity_id"),actor);events.activityResource("ACTIVITY_STOP_TASK_CHANGED","ACTIVITY_STOP",(UUID)previous.getFirst().get("stop_id"),(UUID)t.get("activity_id"),a.activity().getGroupId(),null);}emit(task,actor);return get(task,actor,null);}
 @Transactional public Execution submit(UUID task,UUID actor,Submit r){var t=lock(task,actor);var old=db.queryForList("SELECT task_id,author_id FROM task_evidence WHERE id=?",r.clientRequestId());if(!old.isEmpty()){if(!task.equals(old.getFirst().get("task_id"))||!actor.equals(old.getFirst().get("author_id")))throw journey.invalid();return get(task,actor,null);}if(!assigned(task,actor)||"DONE".equals(t.get("status"))||policy.mode(task).equals("NONE"))throw journey.denied();if(new HashSet<>(r.mediaKeys()).size()!=r.mediaKeys().size())throw journey.invalid();UUID group=journey.readable((UUID)t.get("activity_id"),actor).activity().getGroupId();for(String key:r.mediaKeys())refs.validate(key,UploadCategory.MOMENT_IMAGE,group,actor);
  db.update("UPDATE task_evidence SET status='SUPERSEDED',updated_at=clock_timestamp() WHERE task_id=? AND status='PENDING'",task);boolean direct=policy.mode(task).equals("DIRECT_COMPLETE");db.update("INSERT INTO task_evidence(id,task_id,author_id,source,caption,task_snapshot,status) VALUES (?,?,?,?,?,?,?)",r.clientRequestId(),task,actor,r.source().name(),r.caption().trim(),t.get("updated_at"),direct?"APPROVED":"PENDING");int n=0;for(String key:r.mediaKeys()){var h=storage.head(key);db.update("INSERT INTO task_evidence_media(id,evidence_id,storage_key,content_type,file_name,file_size,sort_order) VALUES (?,?,?,?,?,?,?)",UUID.randomUUID(),r.clientRequestId(),key,h.contentType(),refs.originalFileName(key),h.size(),n++);}if(direct){tasks.changeStatus(task,actor,new UpdateTaskStatusRequest(TaskStatus.DONE));em.flush();}emit(task,actor);return get(task,actor,null);
 }
 @Transactional public Execution review(UUID task,UUID evidence,UUID actor,Review r){lock(task,actor);if(!manager(task,actor))throw journey.denied();var rows=db.queryForList("SELECT * FROM task_evidence WHERE id=? AND task_id=? FOR UPDATE",evidence,task);if(rows.isEmpty())throw journey.missing();var e=rows.getFirst();if(actor.equals(e.get("author_id")))throw journey.denied();var existing=db.queryForList("SELECT * FROM task_evidence_reviews WHERE id=?",r.clientRequestId());if(!existing.isEmpty()){var old=existing.getFirst();if(!evidence.equals(old.get("evidence_id"))||!actor.equals(old.get("reviewer_id"))||!(r.approve()?"APPROVE":"REJECT").equals(old.get("decision"))||!r.reason().trim().equals(old.get("reason")))throw journey.invalid();return get(task,actor,null);}if(!"PENDING".equals(e.get("status")))throw new BusinessException(ErrorCode.CONFLICT);if(r.approve()&&(!view(e,actor).current()||!policy.mode(task).equals("REQUIRE_REVIEW")))throw new BusinessException(ErrorCode.CONFLICT);if(!r.approve()&&r.reason().trim().isEmpty())throw journey.invalid();db.update("INSERT INTO task_evidence_reviews(id,evidence_id,reviewer_id,decision,reason) VALUES (?,?,?,?,?)",r.clientRequestId(),evidence,actor,r.approve()?"APPROVE":"REJECT",r.reason().trim());db.update("UPDATE task_evidence SET status=?,updated_at=clock_timestamp() WHERE id=?",r.approve()?"APPROVED":"REJECTED",evidence);if(r.approve()){tasks.completeReviewedEvidence(task,actor);em.flush();}emit(task,actor);return get(task,actor,null);}
 public MediaAccessResponse media(UUID task,UUID media,UUID actor){get(task,actor,null);var keys=db.queryForList("SELECT m.storage_key FROM task_evidence_media m JOIN task_evidence e ON e.id=m.evidence_id WHERE m.id=? AND e.task_id=?",String.class,media,task);if(keys.isEmpty())throw journey.missing();var url=storage.presignGet(keys.getFirst(),Duration.ofSeconds(60));return new MediaAccessResponse(url.url(),url.expiresAt());}
}
